// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract EtherToken is ERC20, ERC20Burnable, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    uint256 public constant MAX_SUPPLY = 210_000_000_000 * 1e18; // 210 billion
    uint256 public constant GENESIS_ALLOCATION = MAX_SUPPLY * 10 / 100; // 10% for genesis
    uint256 public immutable genesisEnd;

    constructor(address genesisRecipient, uint256 genesisDuration)
        ERC20("Ethercoin", "ETHER")
    {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(BURNER_ROLE, msg.sender);

        // Mint genesis allocation
        _mint(genesisRecipient, GENESIS_ALLOCATION);
        genesisEnd = block.timestamp + genesisDuration;
    }

    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds max supply");
        _mint(to, amount);
    }

    function burnFrom(address account, uint256 amount) public override onlyRole(BURNER_ROLE) {
        _burn(account, amount);
    }
}

contracts/NodeRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract NodeRegistry is AccessControl {
    using SafeERC20 for IERC20;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    enum NodeType { GPU_MINER, PROXY_NODE, VERIFIER }
    enum NodeStatus { UNREGISTERED, ACTIVE, SLASHED, EXITED }

    struct Node {
        NodeType nodeType;
        NodeStatus status;
        address owner;
        string hardwareProofCID;
        uint256 stakeAmount;
        uint256 reputation;
        uint256 tasksCompleted;
        uint256 tasksVerified;
        uint256 registeredAt;
        uint256 lastActive;
    }

    IERC20 public etherToken;
    uint256 public minStakeGPU;
    uint256 public minStakeProxy;
    uint256 public minStakeVerifier;

    uint256 public totalNodes;
    mapping(address => Node) public nodes;
    mapping(NodeType => address[]) public activeNodesByType;
    mapping(address => uint256) public nodeIndex;

    event NodeRegistered(address indexed node, NodeType nodeType, uint256 stake);
    event NodeStatusChanged(address indexed node, NodeStatus status);
    event StakeIncreased(address indexed node, uint256 additional);
    event StakeWithdrawn(address indexed node, uint256 amount);
    event ReputationUpdated(address indexed node, uint256 newScore);

    constructor(
        address _etherToken,
        uint256 _minStakeGPU,
        uint256 _minStakeProxy,
        uint256 _minStakeVerifier
    ) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        etherToken = IERC20(_etherToken);
        minStakeGPU = _minStakeGPU;
        minStakeProxy = _minStakeProxy;
        minStakeVerifier = _minStakeVerifier;
    }

    function register(NodeType nodeType, string calldata hardwareProofCID, uint256 stakeAmount) external {
        require(nodes[msg.sender].status == NodeStatus.UNREGISTERED, "Already registered");
        uint256 requiredStake = _requiredStake(nodeType);
        require(stakeAmount >= requiredStake, "Insufficient stake");

        etherToken.safeTransferFrom(msg.sender, address(this), stakeAmount);

        nodes[msg.sender] = Node({
            nodeType: nodeType,
            status: NodeStatus.ACTIVE,
            owner: msg.sender,
            hardwareProofCID: hardwareProofCID,
            stakeAmount: stakeAmount,
            reputation: 100,
            tasksCompleted: 0,
            tasksVerified: 0,
            registeredAt: block.timestamp,
            lastActive: block.timestamp
        });
        nodeIndex[msg.sender] = activeNodesByType[nodeType].length;
        activeNodesByType[nodeType].push(msg.sender);
        totalNodes++;

        emit NodeRegistered(msg.sender, nodeType, stakeAmount);
    }

    function increaseStake(uint256 additional) external {
        Node storage n = nodes[msg.sender];
        require(n.status == NodeStatus.ACTIVE, "Not active");
        etherToken.safeTransferFrom(msg.sender, address(this), additional);
        n.stakeAmount += additional;
        emit StakeIncreased(msg.sender, additional);
    }

    function requestExit() external {
        Node storage n = nodes[msg.sender];
        require(n.status == NodeStatus.ACTIVE, "Not active");
        n.status = NodeStatus.EXITED;
        _removeFromActiveList(msg.sender, n.nodeType);
        etherToken.safeTransfer(msg.sender, n.stakeAmount);
        n.stakeAmount = 0;
        emit NodeStatusChanged(msg.sender, NodeStatus.EXITED);
    }

    function slash(address nodeAddress, uint256 penaltyPct) external onlyRole(ADMIN_ROLE) {
        Node storage n = nodes[nodeAddress];
        require(n.status == NodeStatus.ACTIVE, "Not active");
        uint256 penalty = n.stakeAmount * penaltyPct / 100;
        n.stakeAmount -= penalty;
        etherToken.safeTransfer(address(0xdead), penalty);
        if (n.stakeAmount < _requiredStake(n.nodeType)) {
            n.status = NodeStatus.SLASHED;
            _removeFromActiveList(nodeAddress, n.nodeType);
            emit NodeStatusChanged(nodeAddress, NodeStatus.SLASHED);
        }
    }

    function updateReputation(address nodeAddress, uint256 newScore) external onlyRole(ADMIN_ROLE) {
        Node storage n = nodes[nodeAddress];
        require(n.status == NodeStatus.ACTIVE, "Not active");
        n.reputation = newScore;
        emit ReputationUpdated(nodeAddress, newScore);
    }

    function recordTask(address nodeAddress) external onlyRole(ADMIN_ROLE) {
        Node storage n = nodes[nodeAddress];
        if (n.status == NodeStatus.ACTIVE) {
            n.tasksCompleted++;
            n.lastActive = block.timestamp;
        }
    }

    function getNodeStatus(address nodeAddress) external view returns (NodeStatus) {
        return nodes[nodeAddress].status;
    }

    function getNodeType(address nodeAddress) external view returns (NodeType) {
        return nodes[nodeAddress].nodeType;
    }

    function getActiveNodes(NodeType nodeType) external view returns (address[] memory) {
        return activeNodesByType[nodeType];
    }

    function _requiredStake(NodeType nodeType) internal view returns (uint256) {
        if (nodeType == NodeType.GPU_MINER) return minStakeGPU;
        if (nodeType == NodeType.PROXY_NODE) return minStakeProxy;
        if (nodeType == NodeType.VERIFIER) return minStakeVerifier;
        return type(uint256).max;
    }

    function _removeFromActiveList(address node, NodeType nodeType) internal {
        address[] storage list = activeNodesByType[nodeType];
        uint256 idx = nodeIndex[node];
        uint256 last = list.length - 1;
        if (idx != last) {
            address lastAddr = list[last];
            list[idx] = lastAddr;
            nodeIndex[lastAddr] = idx;
        }
        list.pop();
        delete nodeIndex[node];
    }
}

contracts/TaskMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./NodeRegistry.sol";

contract TaskMarket is AccessControl {
    using SafeERC20 for IERC20;

    bytes32 public constant RESOLVER_ROLE = keccak256("RESOLVER_ROLE");

    enum TaskStatus { PENDING, ASSIGNED, COMPLETED, CHALLENGED, FINALIZED, DISPUTED }
    enum VerificationMode { OPTIMISTIC, ZK, TEE }

    struct Task {
        uint256 id;
        address creator;
        string modelCID;
        string inputCID;
        uint256 expectedEFLOPS;
        VerificationMode verificationMode;
        uint256 reward;
        uint256 challengeStake;
        TaskStatus status;
        address assignedNode;
        string workProofCID;
        uint256 createdAt;
        uint256 challengeDeadline;
        uint256 finalizedAt;
    }

    IERC20 public etherToken;
    NodeRegistry public nodeRegistry;
    uint256 public nextTaskId;
    uint256 public challengePeriod;
    uint256 public verifierFeeRatio;

    mapping(uint256 => Task) public tasks;
    uint256 public totalTasksCompleted;
    uint256 public totalEFLOPSVerified;

    event TaskCreated(uint256 indexed taskId, address indexed creator, string modelCID, uint256 reward);
    event TaskAssigned(uint256 indexed taskId, address indexed node);
    event TaskCompleted(uint256 indexed taskId, address indexed node, string workProofCID);
    event TaskChallenged(uint256 indexed taskId, address indexed challenger);
    event TaskFinalized(uint256 indexed taskId, bool verified);
    event TaskDisputed(uint256 indexed taskId, address indexed challenger);

    constructor(address _etherToken, address _nodeRegistry, uint256 _challengePeriod, uint256 _verifierFeeRatio) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(RESOLVER_ROLE, msg.sender);
        etherToken = IERC20(_etherToken);
        nodeRegistry = NodeRegistry(_nodeRegistry);
        challengePeriod = _challengePeriod;
        verifierFeeRatio = _verifierFeeRatio;
    }

    function createTask(
        string calldata modelCID,
        string calldata inputCID,
        uint256 expectedEFLOPS,
        VerificationMode verificationMode,
        uint256 reward
    ) external returns (uint256) {
        require(reward > 0, "Reward must be positive");
        uint256 challengeStake = reward * 10 / 100;

        etherToken.safeTransferFrom(msg.sender, address(this), reward + challengeStake);

        uint256 taskId = nextTaskId++;
        tasks[taskId] = Task({
            id: taskId,
            creator: msg.sender,
            modelCID: modelCID,
            inputCID: inputCID,
            expectedEFLOPS: expectedEFLOPS,
            verificationMode: verificationMode,
            reward: reward,
            challengeStake: challengeStake,
            status: TaskStatus.PENDING,
            assignedNode: address(0),
            workProofCID: "",
            createdAt: block.timestamp,
            challengeDeadline: 0,
            finalizedAt: 0
        });

        emit TaskCreated(taskId, msg.sender, modelCID, reward);
        return taskId;
    }

    function assignTask(uint256 taskId, address node) external onlyRole(RESOLVER_ROLE) {
        Task storage t = tasks[taskId];
        require(t.status == TaskStatus.PENDING, "Not pending");
        require(nodeRegistry.getNodeStatus(node) == NodeRegistry.NodeStatus.ACTIVE, "Node not active");

        t.status = TaskStatus.ASSIGNED;
        t.assignedNode = node;
        t.challengeDeadline = block.timestamp + challengePeriod;

        emit TaskAssigned(taskId, node);
    }

    function submitWork(uint256 taskId, string calldata workProofCID) external {
        Task storage t = tasks[taskId];
        require(t.status == TaskStatus.ASSIGNED, "Not assigned");
        require(msg.sender == t.assignedNode, "Not assigned node");

        t.status = TaskStatus.COMPLETED;
        t.workProofCID = workProofCID;

        emit TaskCompleted(taskId, msg.sender, workProofCID);
    }

    function finalizeTask(uint256 taskId) external {
        Task storage t = tasks[taskId];
        require(t.status == TaskStatus.COMPLETED, "Not completed");
        require(block.timestamp >= t.challengeDeadline, "Challenge period not ended");

        t.status = TaskStatus.FINALIZED;
        t.finalizedAt = block.timestamp;

        uint256 nodeReward = t.reward * (100 - verifierFeeRatio) / 100;
        uint256 verifierFee = t.reward - nodeReward;

        etherToken.safeTransfer(t.assignedNode, nodeReward);
        etherToken.safeTransfer(t.creator, t.challengeStake);

        nodeRegistry.recordTask(t.assignedNode);

        totalTasksCompleted++;
        totalEFLOPSVerified += t.expectedEFLOPS;

        emit TaskFinalized(taskId, true);
    }

    function challengeTask(uint256 taskId) external {
        Task storage t = tasks[taskId];
        require(t.status == TaskStatus.COMPLETED, "Not completed");
        require(block.timestamp < t.challengeDeadline, "Challenge period ended");
        require(nodeRegistry.getNodeStatus(msg.sender) == NodeRegistry.NodeStatus.ACTIVE, "Only active verifiers");

        t.status = TaskStatus.CHALLENGED;
        emit TaskChallenged(taskId, msg.sender);
    }

    function resolveChallenge(uint256 taskId, bool nodeHonest) external onlyRole(RESOLVER_ROLE) {
        Task storage t = tasks[taskId];
        require(t.status == TaskStatus.CHALLENGED, "Not challenged");

        t.status = TaskStatus.FINALIZED;
        t.finalizedAt = block.timestamp;

        if (nodeHonest) {
            uint256 nodeReward = t.reward * (100 - verifierFeeRatio) / 100;
            etherToken.safeTransfer(t.assignedNode, nodeReward);
            etherToken.safeTransfer(t.creator, t.challengeStake);
            totalTasksCompleted++;
            totalEFLOPSVerified += t.expectedEFLOPS;
        } else {
            uint256 penalty = t.reward * 50 / 100;
            etherToken.safeTransfer(t.creator, t.reward + t.challengeStake + penalty);
            nodeRegistry.slash(t.assignedNode, 50);
        }
        emit TaskFinalized(taskId, nodeHonest);
    }

    function getTask(uint256 taskId) external view returns (Task memory) {
        return tasks[taskId];
    }
}

